 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');ev=read(RUN/'event-outcomes.json')
