 evidence={'build':'1003x1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'event_outcomes':ev,'scope':'BTC-only development; ordinary non-holiday last Friday at 16 London, not a recovered actual CME expiry calendar; no accepted strategy'}
